    () => ({
      ...DEFAULT_MATERIAL,
      depth: 40,
      chromaAmount: 0.4,
      scaleX: 0.07,
      scaleY: 0.07,
      blurAmount: 0.5,
      sdfBoundary: true,
      edgeFalloff: true,
      brightness: 0.12,
      specularStrength: 1,
      specularRotation: 45,
      glowStrength: 0.1,
      glowSpread: 1,
      glowExponent: 0.5,
      edgeStrength: 0.25,
      edgeWidth: 3,
      edgeExponent: 1.5,
      domeDepth: IDLE_LENS * mobileScale,
      splayAmount: 1
    }),
    [mobileScale]
  );

  return (
    <div
      ref={stageRef}
      className="readable-example readable-hero-stage"
      onPointerEnter={() => {
        if (leaveTimerRef.current !== undefined) {
          window.clearTimeout(leaveTimerRef.current);
        }
        hoverRef.current = true;
        pointerTargetRef.current = {
