      collapse();
      setChecked(next);
      animatePosition(next ? TRAVEL : 0);
      return;
    }

    if (mode.current === 'pending') {
      mode.current = 'tap';
      expand();
      const next = !checked;
      setChecked(next);
      animatePosition(next ? TRAVEL : 0);
      releaseTimer.current = window.setTimeout(() => {
        mode.current = 'idle';
        collapse();
      }, 330);
      return;
    }

    mode.current = 'idle';
    collapse();
    animatePosition(checked ? TRAVEL : 0);
  };

